Fonksiyon, Kahn'ın algoritmasını (Kahn's Algorithm) bir `heapq` (min-heap) kullanarak genişleterek, aynı anda kurulabilen paketler arasında alfabetik olarak en küçük olanın seçilmesini garanti eder. Döngü durumunda ise DFS (Depth First Search) algoritması ile döngüdeki düğümler tespit edilmekte ve döngü alfabetik olarak en küçük düğümden başlayacak şekilde paketlenmektedir.

```python
import collections
import heapq

class DongluHatasi(ValueError):
    """Döngüsel bağımlılık durumunda fırlatılan hata."""
    def __init__(self, dongu: list[str]):
        self.dongu = dongu
        super().__init__(f"Döngü bulundu: {' -> '.join(dongu)}")

def kurulum_sirasi(deps: dict[str, list[str]]) -> list[str]:
    # 1. Tüm paketleri belirle (açıkça belirtilenler + bağımlılık olarak geçenler)
    all_nodes = set(deps.keys())
    for neighbors in deps.values():
        for n in neighbors:
            all_nodes.add(n)

    # 2. Graf yapısını kur
    adj = {node: set(deps.get(node, [])) for node in all_nodes}

    # Kahn's Algorithm hazırlığı
    # graph: v -> [u1, u2] (v kurulunca u1 ve u2'nin bağımlılığı azalır)
    graph = collections.defaultdict(list)
    in_degree = {node: 0 for node in all_nodes}

    for u in all_nodes:
        for v in adj[u]:
            # u'nun v'ye bağımlılığı var (v önce kurulmalı)
            graph[v].append(u)
            in_degree[u] += 1

    # Lexicographical Topological Sort (Alfabetik sıralama için Min-Heap)
    ready = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(ready)

    result = []
    while ready:
        u = heapq.heappop(ready)
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(ready, v)

    if len(result) < len(all_nodes):
        # Döngü var. DFS ile döngü düğümlerini tespit et.
        def find_any_cycle():
            visited = set()
            stack = []
            stack_set = set()

            def dfs(u):
                visited.add(u)
                stack.append(u)
                stack_set.add(u)

                for v in adj[u]:
                    if v in stack_set:
                        idx = stack.index(v)
                        return stack[idx:]
                    if v not in visited:
                        res = dfs(v)
                        if res: return res

                stack.pop()
                stack_set.remove(u)
                return None

            for node in sorted(all_nodes):
                if node not in visited:
                    cycle = dfs(node)
                    if cycle:
                        min_node = min(cycle)
                        min_idx = cycle.index(min_node)
                        return cycle[min_idx:] + cycle[:min_idx]
            return None

        cycle = find_any_cycle()
        if cycle:
            raise DongluHatasi(cycle)
        raise ValueError("Döngü tespit edildi ancak yapı karmaşık.")

    return result
```

