def test_kurulum_sirasi():
    from bagimlilik import kurulum_sirasi, DongluHatasi

    # Test 1: Basit sıralama ve alfabetik sıra
    deps1 = {"B": ["A"], "C": ["A"], "A": []}
    assert kurulum_sirasi(deps1) == ["A", "B", "C"]

    # Test 2: Daha karmaşık bağımlılıklar
    deps2 = {"D": ["B", "C"], "B": ["A"], "C": ["A"], "A": []}
    assert kurulum_sirasi(deps2) == ["A", "B", "C", "D"]

    # Test 3: Alfabetik öncelik
    deps3 = {"C": ["A"], "B": ["A"], "A": []}
    assert kurulum_sirasi(deps3) == ["A", "B", "C"]

    # Test 4: Kendine bağımlılık (Döngü)
    deps4 = {"A": ["A"]}
    try:
        kurulum_sirasi(deps4)
        assert False, "Döngü hatası fırlatılmadı"
    except DongluHatasi as e:
        assert e.dongu == ["A"]

    # Test 5: Çoklu paket döngüsü
    deps5 = {"A": ["B"], "B": ["C"], "C": ["A"], "D": []}
    try:
        kurulum_sirasi(deps5)
        assert False, "Döngü hatası fırlatılmadı"
    except DongluHatasi as e:
        # Döngü: A->B->C->A. Alfabetik en küçük A.
        assert e.dongu == ["A", "B", "C"]

    # Test 6: Dolaylı döngü
    deps6 = {"A": ["B"], "B": ["C"], "C": ["A"]}
    try:
        kurulum_sirasi(deps6)
        assert False, "Döngü hatası fırlatılmadı"
    except DongluHatasi as e:
        assert e.dongu == ["A", "B", "C"]

    # Test 7: Karmaşık döngü içermeyen ama karmaşık yapı
    deps7 = {"A": ["B", "C"], "B": ["D"], "C": ["D"], "D": []}
    assert kurulum_sirasi(deps7) == ["D", "B", "C", "A"]

    # Test 8: Boş girdi
    assert kurulum_sirasi({}) == []

    # Test 9: Paketlerden biri bağımlılık olarak var ama deps sözlüğünde yoksa (implicit)
    # Soruda "Tüm paketleri (yalnızca bağımlılık olarak geçenler dahil)" diyor.
    deps9 = {"A": ["B"]} # B'nin bağımlılığı yok, o yüzden B boş liste sayılmalı
    assert kurulum_sirasi(deps9) == ["B", "A"]

    print("Tüm testler geçti!")

if __name__ == "__main__":
    test_kurulum_sirasi()

